<div class="page-title"><div><p class="eyebrow">Workflow: create → add questions → preview → publish</p><h1>Quizzes</h1></div><a class="btn btn-sm" href="<?= e(url('/admin/quizzes/new')) ?>">+ Create quiz</a></div>
<?php if (!$rows): ?><div class="card empty">No quizzes yet. Create one, add questions, then publish it.</div><?php endif; ?>
<div class="table-wrap"><table class="cards-sm"><thead><tr><th>Title</th><th>Status</th><th>Questions</th><th>Marks</th><th>Opens</th><th>Closes</th><th>Attempts</th><th>Completed / avg</th><th>Actions</th></tr></thead><tbody>
<?php foreach ($rows as $r): ?><tr><td data-l="Title"><strong><?= e($r['title']) ?></strong><br><small><?= e($r['category']) ?></small></td><td data-l="Status"><?= badge($r['status']) ?></td><td data-l="Questions"><?= (int)$r['qn'] ?></td><td data-l="Marks"><?= (int)$r['marks'] ?></td>
<td data-l="Opens"><?= e(fmt_dt($r['opens_at'])) ?></td><td data-l="Closes"><?= e(fmt_dt($r['closes_at'])) ?></td><td data-l="Attempts"><?= (int)$r['attempts'] ?></td><td data-l="Completed / avg"><?= (int)$r['done'] ?> · <?= $r['avg'] === null ? 'n/a' : e(num(round((float)$r['avg'], 1))) . '%' ?></td>
<td data-l="Actions" class="acts"><a href="<?= e(url('/admin/quizzes/' . $r['id'] . '/questions')) ?>">Questions</a> · <a href="<?= e(url('/admin/quizzes/' . $r['id'] . '/edit')) ?>">Edit</a> · <a href="<?= e(url('/admin/quizzes/' . $r['id'] . '/preview')) ?>">Preview</a>
  <form class="inline" method="post" action="<?= e(url('/admin/quizzes/' . $r['id'] . '/status')) ?>"><?= csrf_field() ?><select name="status" aria-label="Status" data-confirm-values="closed,archived"><?php foreach (QUIZ_STATUSES as $s): ?><option <?= $r['status'] === $s ? 'selected' : '' ?>><?= $s ?></option><?php endforeach; ?></select><button class="btn btn-sm" type="submit">Set</button></form>
  <form class="inline" method="post" action="<?= e(url('/admin/quizzes/' . $r['id'] . '/duplicate')) ?>"><?= csrf_field() ?><button class="btn btn-sm btn-outline" type="submit">Duplicate</button></form></td></tr>
<?php endforeach; ?></tbody></table></div>
